<?php if (!empty($objects)) : ?><div class="row"><div class="portlet light"><div class="portlet-body"><form action="<?= $o_path ?>" method="post"><div class="table-scrollable"><table class="table table-bordered table-striped"><thead><tr><th>Порядок</th><th>Название</th><th>Статус</th><th>Действия</th></tr></thead><tbody>
<?php foreach ($objects as $item) : ?><tr><td><input class="form-control" type="number" name="so[<?= (int) $item->id ?>]" value="<?= (int) $item->sorder ?>" style="width:90px"></td><td><a href="<?= $e_path . (int) $item->id ?>"><?= htmlspecialchars($item->titleRU, ENT_QUOTES, 'UTF-8') ?></a></td><td><?= !empty($item->isShown) ? 'Опубликована' : 'Скрыта' ?></td><td><a class="btn btn-xs green-stripe" href="<?= $e_path . (int) $item->id ?>">Изменить</a> <a class="btn btn-xs red-stripe mine_delete_row" href="<?= $del_path . (int) $item->id ?>">Удалить</a></td></tr><?php endforeach; ?>
</tbody></table></div><button class="btn green" type="submit">Сохранить порядок</button></form></div></div></div><?php endif; ?>
<script>(function(){var root=document.querySelector('.beauty-selection-picker');if(!root)return;var input=root.querySelector('[data-product-search]'),results=root.querySelector('[data-product-results]'),selected=root.querySelector('[data-product-selected]'),ids={};function add(p){if(ids[p.id])return;ids[p.id]=1;var row=document.createElement('span');row.style.cssText='display:inline-block;padding:6px 10px;margin:0 6px 6px 0;background:#eef2f5;border-radius:3px';row.innerHTML=(p.titleRU||p.titleRO||'Товар')+' <small>#'+p.id+'</small> <button type="button" data-remove style="border:0;background:none;color:#c00">×</button><input type="hidden" name="product_ids[]" value="'+p.id+'">';row.querySelector('[data-remove]').onclick=function(){delete ids[p.id];row.remove()};selected.appendChild(row)}function search(){var q=input.value.trim();if(q.length<2){results.innerHTML='';return}fetch(root.dataset.lookup+'?q='+encodeURIComponent(q)).then(function(r){return r.json()}).then(function(list){results.innerHTML=list.map(function(p){return '<button type="button" class="btn btn-xs default" data-id="'+p.id+'" style="margin:0 5px 5px 0">'+(p.titleRU||p.titleRO)+' (#'+p.id+')</button>'}).join('');results.querySelectorAll('[data-id]').forEach(function(b){b.onclick=function(){var p=list.find(function(x){return String(x.id)===b.dataset.id});add(p);input.value='';results.innerHTML=''}})});}input.addEventListener('input',search)})();</script>
